-- Generated by tools/gen_ddl.py from the CEDARS catalog (manual v19.0). Do not edit.
CREATE TABLE IF NOT EXISTS ${catalog}.silver.student_grade_history (
  school_year INT NOT NULL COMMENT 'CEDARS H01 – School Year',
  county_district_code STRING NOT NULL COMMENT 'CEDARS H02 – Serving County District Code [code set: county_district]',
  district_student_id STRING COMMENT 'CEDARS H03 – District Student ID',
  ssid STRING NOT NULL COMMENT 'CEDARS H04 – State Student ID (SSID)',
  course_id STRING NOT NULL COMMENT 'CEDARS H07 – Course ID',
  course_title STRING COMMENT 'CEDARS H08 – Course Title',
  grade_level_code STRING COMMENT 'CEDARS H09 – Grade Level Code [code set: grade_level]',
  letter_grade STRING COMMENT 'CEDARS H10 – Letter Grade [code set: letter_grade]',
  credits_attempted DECIMAL(4,2) COMMENT 'CEDARS H11 – Credits Attempted',
  credits_earned DECIMAL(4,2) COMMENT 'CEDARS H12 – Credits Earned',
  course_designation_codes ARRAY<STRING> COMMENT 'CEDARS H13 – Course Designation Code [code set: course_designation] (split into single characters)',
  course_designation_codes_raw STRING COMMENT 'CEDARS H13 – Course Designation Code [code set: course_designation] (as reported)',
  content_area_code STRING COMMENT 'CEDARS H14 – Content Area Code [code set: content_area]',
  state_course_code STRING COMMENT 'CEDARS H15 – State Course Code [code set: avid_school, state_course]',
  ap_ib_ci_course_code STRING COMMENT 'CEDARS H16 – Advanced Placement (AP) and International Baccalaureate (IB) Code and Cambridge International Program [code set: ap_ib_cambridge_course]',
  cip_code STRING COMMENT 'CEDARS H17 – Classification of Instructional Program (CIP) Code Number [code set: cip]',
  term_end_month STRING COMMENT 'CEDARS H18 – Term End Date',
  term STRING COMMENT 'CEDARS H19 – Term [code set: term]',
  cte_assessment_code STRING COMMENT 'CEDARS H24 – Did the Student Take or Pass a State or Nationally Recognized Assessment of Technical Skill and Knowledge? [code set: cte_assessment]',
  teacher_certification_number STRING COMMENT 'CEDARS H25 – Certification Number',
  school_code STRING NOT NULL COMMENT 'CEDARS H26 – School Code [code set: school]',
  ale_course_type_code STRING COMMENT 'CEDARS H27 – ALE Course Type [code set: ale_course_type]',
  course_school_year INT NOT NULL COMMENT 'CEDARS H30 – Course School Year',
  industry_certification_codes_earned ARRAY<STRING> COMMENT 'CEDARS H31 – Industry Recognized Certifications Earned [code set: industry_certification] (split on comma, trimmed)',
  industry_certification_codes_earned_raw STRING COMMENT 'CEDARS H31 – Industry Recognized Certifications Earned [code set: industry_certification] (as reported)',
  work_based_learning_codes ARRAY<STRING> COMMENT 'CEDARS H32 – Student Work-Based Learning Activities [code set: work_based_learning_activity] (split on comma, trimmed)',
  work_based_learning_codes_raw STRING COMMENT 'CEDARS H32 – Student Work-Based Learning Activities [code set: work_based_learning_activity] (as reported)',
  term_key STRING NOT NULL COMMENT 'Derived: CEDARS H19 with NULL as \'\' (transfer credits have no term); dedupe-key member (C-006)',
  term_end_month_date DATE COMMENT 'Derived: first day of the month in CEDARS H18 (MM/YYYY)',
  is_out_of_district BOOLEAN COMMENT 'Derived: CEDARS H26 = 9999 (course taken outside the serving district)',
  is_current_version BOOLEAN COMMENT 'Derived: latest reported version of this SSID + H30 + H19 + H26 + H07 across submissions (design §6)',
  _source_file STRING COMMENT 'Load metadata: submitted file name',
  _school_year INT COMMENT 'Load metadata: school year of the submission (ending year, e.g. 2027)',
  _manual_version STRING NOT NULL COMMENT 'Load metadata: CEDARS manual version the file conforms to (backload seam)',
  _submission_type STRING NOT NULL COMMENT 'Load metadata: submission type (e.g. year-end final)',
  _load_ts TIMESTAMP COMMENT 'Load metadata: load timestamp',
  _record_hash STRING COMMENT 'Load metadata: hash of the typed business columns, for change detection',
  _dq_issues ARRAY<STRING> COMMENT 'Load metadata: IDs of failed non-rejecting checks: IR### (catalog/integrity_rules.csv) or DQ### (docs/silver-contract.md)',
  CONSTRAINT student_grade_history_pk PRIMARY KEY (school_year, county_district_code, ssid, course_school_year, term_key, school_code, course_id, _submission_type)
)
USING DELTA
CLUSTER BY (school_year, county_district_code)
COMMENT 'CEDARS File H – Student Grade History File (H). Grain: This file contains all high school credit courses where credit was attempted for every student served during the current school year, including those students who exit the school.'
TBLPROPERTIES (
  'cedars.file_code' = 'H',
  'cedars.manual_version' = '19.0'
);
